public class ClockDurationTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        check("new ClockDuration(0, 90, 75).toString()", "1:31:15",
                safe(() -> new ClockDuration(0, 90, 75).toString()));
        check("new ClockDuration(0, 90, 75).getMinutes()", 31,
                safe(() -> new ClockDuration(0, 90, 75).getMinutes()));
        check("new ClockDuration(1, -30, 0).toString()", "0:30:00",
                safe(() -> new ClockDuration(1, -30, 0).toString()));
        check("new ClockDuration(0, 5, 9).toString()", "0:05:09",
                safe(() -> new ClockDuration(0, 5, 9).toString()));
        check("new ClockDuration(2, 0, 0).totalSeconds()", 7200,
                safe(() -> new ClockDuration(2, 0, 0).totalSeconds()));
        check("plus", "3:00:00",
                safe(() -> new ClockDuration(1, 45, 30).plus(new ClockDuration(1, 14, 30)).toString()));
        check("plus leaves the original alone", "1:45:30",
                safe(() -> {
                    ClockDuration base = new ClockDuration(1, 45, 30);
                    base.plus(new ClockDuration(0, 0, 10));
                    return base.toString();
                }));
        check("minus", "0:44:30",
                safe(() -> new ClockDuration(1, 0, 0).minus(new ClockDuration(0, 15, 30)).toString()));
        check("minus clamps at zero", "0:00:00",
                safe(() -> new ClockDuration(0, 0, 30).minus(new ClockDuration(0, 5, 0)).toString()));

        String thrown = "no exception";
        try {
            new ClockDuration(0, -1, 0);
        } catch (IllegalArgumentException e) {
            thrown = "IllegalArgumentException";
        } catch (Throwable t) {
            thrown = t.getClass().getSimpleName();
        }
        check("negative total is rejected", "IllegalArgumentException", thrown);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

