public class ClockDuration {

    private final int totalSeconds;

    public ClockDuration(int hours, int minutes, int seconds) {
        int total = hours * 3600 + minutes * 60 + seconds;
        if (total < 0) {
            throw new IllegalArgumentException("duration cannot be negative");
        }
        this.totalSeconds = total;
    }

    public int totalSeconds() {
        return totalSeconds;
    }

    public int getHours() {
        return totalSeconds / 3600;
    }

    public int getMinutes() {
        return (totalSeconds % 3600) / 60;
    }

    public int getSeconds() {
        return totalSeconds % 60;
    }

    public ClockDuration plus(ClockDuration other) {
        return new ClockDuration(0, 0, totalSeconds + other.totalSeconds);
    }

    public ClockDuration minus(ClockDuration other) {
        int result = totalSeconds - other.totalSeconds;
        if (result < 0) {
            result = 0;
        }
        return new ClockDuration(0, 0, result);
    }

    @Override
    public String toString() {
        return String.format(java.util.Locale.US, "%d:%02d:%02d", getHours(), getMinutes(), getSeconds());
    }
}
